#!/usr/bin/env python3
# SunCalc-эмуляция: печатает положение Солнца по времени (Москва, 2025-06-21).
import sys
TABLE = [
    ("08:00",  98, 25), ("08:30", 105, 30), ("09:00", 113, 36),
    ("09:30", 121, 40), ("09:40", 130, 43), ("10:00", 137, 48),
    ("10:30", 145, 54), ("11:00", 153, 60),
]
def main():
    t = sys.argv[1] if len(sys.argv) > 1 else None
    if t:
        for hh, az, el in TABLE:
            if hh == t:
                print(f"time {hh}  azimuth={az}.0  elevation={el}.2")
                return
        print(f"time {t}: нет данных")
        return
    print("SunCalc (эмуляция), Москва 55.75N 37.62E, 2025-06-21, UTC+3")
    print("time    azimuth  elevation")
    for hh, az, el in TABLE:
        print(f"{hh}    {az:>4}      {el:>3}")
if __name__ == "__main__":
    main()

